def glom(target, spec, **kwargs):
    scope = kwargs.pop('scope', _DEFAULT_SCOPE)
    default = kwargs.pop('default', _MISSING)

    if kwargs:
        raise TypeError('glom() got unexpected keyword arguments: %r' % list(kwargs.keys()))

    try:
        return scope[glom](target, spec, scope)
    except Exception as e:
        if default is not _MISSING:
            return default
        if isinstance(e, GlomError) and default is _MISSING:
            raise
        raise GlomError.wrap(e)
